public display NoYesId displayLoadPickComplete()
{
    WMSPickingRoute                     wmsPickingRoute;
    METSalesOrderShipmentLoadLines      shipmentLoadLines;

    select firstonly RecId from wmsPickingRoute
        exists join shipmentLoadLines
            where   shipmentLoadLines.PickingListNum == wmsPickingRoute.pickingRouteID  &&
                    shipmentLoadLines.ShipmentId == this.ShipmentId &&
                    wmsPickingRoute.expeditionStatus != WMSExpeditionStatus::Complete;

    if (wmsPickingRoute.RecId != 0)
    {
        return NoYes::No;
    }
    else
    {
        return NoYes::Yes;
    }
}

